<template lang="pug">
  section.contact#contact
    .contact__wrapper
      .contact__description.description
        .description__title-with-line.title-with-line
          .title-with-line__text contact us
          .title-with-line__line
        .description__text_normal Call us or use the form below
      .contact__feedback.feedback
        .feedback__form
          form(@submit.prevent)
            base-input(
              name="name"
              placeholder="Name"
              autocomplete="on"
              v-model="name"
            )
            base-input(
              name="email"
              placeholder="E-mail"
              autocomplete="on"
              v-model="email"
            )
            base-textarea(
              name="massage"
              placeholder="Message"
              v-model="massage"
            )
            main-button.mt-20(
              :tag="'send'"
              :theme="'gray'"
              @onClick="formSubmit"
            )
        .feedback__inform.inform
          .inform__block
            p.inform__text info@zeus3000.com
          .inform__block.inform__block_mt-20.inform__block_disabled
            p.inform__text ??
      .contact__footer
        a(href="documents/Terms_of_use.pdf" download="" title="download pdf") Terms of Use
      .contact__inform.inform
        .inform__block
          .inform__image.inform__image_email
          p.inform__text info@zeus3000.com
        .inform__block.inform__block_disabled
          .inform__image.inform__image_phone
          p.inform__text ??
</template>

<script>
import BaseInput from '@/components/BaseInput';
import BaseTextarea from '@/components/BaseTextarea';
import MainButton from '@/components/MainButton';

export default {
  name: "partners-section",
  components: {
    BaseInput,
    BaseTextarea,
    MainButton
  },
  data: () => ({
    name: "",
    email: "",
    massage:"",
  }),
  methods: {
    formSubmit: function () {
      console.log(this.name + ' ' + this.email + ' ' + this.massage)
      
    }
  }
}

</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.contact {
  position: relative;
  padding-top: 68px;
  padding-bottom: 96px;
  background-image: url("~@/assets/images/contact/background.png");
  background-repeat: no-repeat;
  //background-position: 50% 50%;
  background-size: cover;

   &::after {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    left: 0;
    bottom: 0;
    background: $overlayContactUs;
    z-index: 1;
  }
   
  &__wrapper {
    @include wrapper();
  }
 
  .description {
    text-shadow: 0px 4px 10px rgba(0, 0, 0, 0.7);
    text-align: left;

    &__text {

      &_normal {
        @include baseText(Regular, 24px);
        line-height: 40px;
        padding-top: 42px;
      }
    }
  }

  &__feedback {
    margin-top: 50px;
  }

  .feedback {
    @include baseRow(space-between, flex-start);
  
    &__form {
      //width: 40%;
    }

    &__inform {
      @include baseText(Bold, 36px);
      text-align: right;
      text-shadow: 0px 4px 20px rgba(0, 0, 0, 0.3);
      margin-top: 22px;
    }
  }

  .inform {

    &__block {
      margin: 0;

      &_mt-20 {
        margin-top: 20px;
      }

      &_disabled {
        display: none;
      }
    }

    &__image {
      margin-right: 10px;

      &_phone {
          @include headerTitleImage(20px, 20px, "~@/assets/images/contact/phone.svg");
      }

      &_email {
          @include headerTitleImage(20px, 20px, "~@/assets/images/contact/email.svg");
      }
    }
  }

  &__footer {
    position: relative;
    font-size: 24px;
    margin-top: 80px;
    
    ::after {
      content: '';
      position: absolute;
      top: 50%;
      right: 0px;
      height: 1px;
      width: 40%;
      background-color: $mainTextColor;
    }

    ::before {
      content: '';
      position: absolute;
      top: 50%;
      left: 0px;
      height: 1px;
      width: 40%;
      background-color: $mainTextColor;
    }

    a {
      text-decoration: none;
      color: $mainTextColor;
    }
  }

  &__inform {
    margin-top: 20px;
    display: none;
  }
  
  .mt-20 {
    margin-top: 20px;
  }
}

@media (max-width: 1200px){
  .contact{
    &__wrapper {
      width: 98%;
    }
  } 
}

@media (max-width: 992px){
  .contact {

    .description__text_normal{
      padding-top: 24px;
    }
    .feedback{
      width: 95%;
      margin: 50px auto 0 auto;
    }
    .feedback__inform{
      @include baseText(Bold, 30px);
    }

    .feedback__form{
      width: 55%;
    }

    .main-button{
      width: 100%;
    }
  }
}

@media (max-width: 768px){
  .contact{
    padding: 25px 0px;
    background-image: url("~@/assets/images/contact/background_adaptive.png");

    &__wrapper{
      width: 100%;
    }

    &__footer ::before, ::after{
      content: none;
    }

    &__footer{
      width: 80%;
      position: static;
      text-align: left;
      padding: 15px 0;
      font-size: 25px;
      margin: 0 auto;
      border-bottom: 1px solid #fff;

      a{
        display: block;
        width: 100%;
      }
    }

    .description{
      width: 90%;
      margin: auto;

      &__text_normal{
        padding-top: 10px;
        font-size: 20px;
      }
    }

    .feedback{
      flex-direction: column;
      margin-top: 0;
      display: block;

      &__form{
        margin: auto;
        width: 80%;
      }

      &__info{
        display: none;
      }

      &__media__info{
        @include baseText(Bold, 36px);
        text-shadow: 0px 4px 20px rgba(0, 0, 0, 0.3);
        margin: 30px auto;
        width: 90%;
        display: flex;
        font-size: 18px;
        text-align: center;
        justify-content: space-around;
      }

      &__email {
       display: flex;
      }

      &__phone {
        display: flex;
        margin: 0;
        align-items: center;
      }

      &__image__email{
        @include headerTitleImage(20px, 20px, "~@/assets/images/contact/email.svg");
        margin: 0 10px;
      }

      &__image__phone{
        @include headerTitleImage(20px, 20px, "~@/assets/images/contact/phone.svg");
        margin: 0 10px;
      }

      &__text{
        font-size: 18px;
        margin: 0;
      }
    }

    .main-button{
      width: 100%;
      opacity: 0.9;
    }

    &__footer {
      width: 90%;
      font-size: 18px;
    }

    &__inform {
      @include baseText(Bold, 14px);
      display: flex;
      align-items: center;
      justify-content: space-around;
    }

    .feedback {

      &__form{
        width: 90%;
      }

      &__inform {
        display: none;
      }
    }

    &__inform {
      @include baseText(Bold, 16px);
    }

    .inform {

      &__block {
        display: flex;

        &_mt-20 {
          margin-top: 20px;
        }

        &_disabled {
          display: none;
        }
      }
    }
  } 
}

@media (max-width: 425px){
  
  .contact {

    &__footer {
      width: 90%;
      font-size: 18px;
    }

    &__inform {
      @include baseText(Bold, 12px);
    }

    .feedback {

      &__form{
        width: 90%;
      }
    }
  } 
}


</style>