<template lang="pug">
  .popup__link
    .link(
      :class="{hoverLink: checkNameHoverLink(link.name)}"
      @mouseover="setNameHoverLink(link.name)" 
      @mouseout="setNameHoverLink()"
      v-model="hoverLinkName"
    )
      .link__wrapper
        a.link__url(
          :href="link.href"
        ) {{link.name}}
        .arrow 
          .arrow__right
      .link__slider
        .arrow 
          .arrow__right.border-left-color

</template>

<script>

export default {
  name: "popup-link",
  components: {
    
  },
  props: {
    purchaseLinks: {
      type: Array,
      required: false,
    },
    link: {
      type: Object,
      required: false,
    },
    hoverLinkName: {
      type: String,
      required: false,
      default: "",
    }
  },
  data: () => ({
   
  }),
  methods: {
    setNameHoverLink: function(linkName) {
      if(linkName) return this.$emit("update:hoverLinkName", linkName)
      return this.$emit("update:hoverLinkName", '')
    },
    checkNameHoverLink: function(linkName) {
      if (this.hoverLinkName == linkName) return true        
      return false
    }
  },
}
</script>

<style lang="scss" scoped>
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.link {
  position: relative;
  margin-top: 33px;

  &__overflor {
    width: 0;
    height: 100%;
  }

  &__wrapper {
    height: 50px;
    background-color: #EAEAEA;
  }

  &__url {
    position: relative;
    width: 100%;
    height: 100%;
    padding-left: 10px;
    display: inline-block;
    text-align: left;
    color: $secondTextColor;
    line-height: 50px;
    text-decoration: none;
    z-index: 5;
  }

  &__slider {
    width: 100%;
    height: 100%;
    background: linear-gradient(167.78deg, rgba(99, 16, 101, 0.8) 10.79%, rgba(45, 22, 188, 0.664) 49.46%, rgba(23, 70, 193, 0.8) 84.31%);
    position: absolute;
    top: 0;
    right: 105%;
    transition: all 1.5s ease;
    
  }

  &.hoverLink {

    .link__slider {
      animation: moveSlidererLink 2.5s ease-out;
      animation-fill-mode: both;
    }

    .link__url {
      color: $mainTextColor;
    }
  }

  // .notHoverLink {

  //   .link__slider {
  //     animation: moveBackSlidererLink 2.5s ease-out;
  //     animation-fill-mode: both;
  //   }

  //   .link__url {
  //     animation: moveSliderer 2s ease-in-out;
  //   }
  // }
}

.arrow {
  width: 50px;
  height: 50px;
  position: absolute;
  top: 0;
  right: -23px;
  
  &__right {
    border: medium solid transparent;
    position: absolute;
    border-color: rgba(255, 212, 52, 0) rgba(255, 212, 52, 0) rgba(255, 212, 52, 0) #EAEAEA;
    border-width: 25px;
    top: 0;
    bottom: 0;
    right: 8px;
    border-right: hidden;
    border-left-width: 15px;
  }
}

.border-left-color {
  border-left-color: rgba(23, 70, 193, 0.8);
}

@keyframes moveSlidererLink {
  0% {
    right: 90%;
    
  }
  100% {
    right: 0%;
    
  }
}

// @keyframes moveBackSlidererLink {
//   0% {
//     right: 0%;
//   }
//   100% {
//     right: 90%;
//   }
// }

@media (max-width:425px) {
  .link {
    margin-top: 15px;

    &__wrapper {
      border-radius: 5px;
      background: linear-gradient(149.65deg, rgba(99, 16, 101, 0.9) 10.79%, rgba(45, 22, 188, 0.747) 49.46%, rgba(23, 70, 193, 0.9) 84.31%);
    }

    &__url {
      padding-left: 0px;
      text-align: center;
    }

    &__slider {
      display: none;
    }
  }

  .arrow {
    display: none;
  }
}

</style>
