<template lang="pug">
  nav.header__menu(:class="{open: checkShowMenu}")
    .header__menu-button(@click="clickMenuButton")
      .menu-button
        .menu-button-line
    .header__menu-lists(:class="{active: checkShowMenu}")
      ul 
        li(
          v-for="headerMenuList of headerMenuLists"
          :key="headerMenuList.title"
        )
          a(
            :href="'#' + headerMenuList.title | cutStringToSpace"
            :name="headerMenuList.title | cutStringToSpace"
            @click="scroll"
          ) {{headerMenuList.title}}
</template>

<script>

export default {
  props: {
    headerMenuLists: {
      type: Array,
      required: false
    }
  },
  data: () => ({
    checkShowMenu: false,
  }),
  filters: {
    cutStringToSpace(value) {
      //return value.indexOf(' ') ? value : value.slice(0, value.indexOf(' '))
      if (value.indexOf(' ') == -1) {
        return value
      } else {
        return value.slice(0, value.indexOf(' '))
      }
    }
  },
  methods: {
    scroll: function(event) {
      let menuListName = event.target.name
      let sectionElement = document.getElementById(menuListName);
      
      event.preventDefault()
      
      sectionElement.scrollIntoView({block: "start", behavior: "smooth"});
      this.clickMenuButton()
    },

    clickMenuButton: function() {
      this.checkShowMenu = !this.checkShowMenu
    }
  }
}
</script>
<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.header__menu {
  position: relative;
  padding-top: 33px;
  font-size: 18px;
  text-transform: uppercase;
  z-index: 3;

  &.open {

    .header__menu-lists {
      display: block;
    }


    .header__menu-button {
      background-color: transparent;
      
      .menu-button {
              
        &::before {
          top: 7px;
          transform: rotate(-45deg);
        }
        
        &::after {
          bottom: 7px;
          transform: rotate(45deg);
        }
        
        &-line {
          opacity: 0
        }
      }
    }  
  }

  .header__menu-button {
    display: none;
    align-items: center;
    justify-content: center;
    position: fixed;
    top: 15px;
    right: 15px;
    width: 35px;
    height: 35px;
    background-color: mainButtonColor();
    border-radius: 5px;
    opacity: 0.75;
    z-index: 9999999;

    .menu-button {
      position: relative;
      width: 16px;
      height: 16px;
      //display: none;
      display: flex;
      align-items: center;
      
      &::before {
        @include menuPsev ('topLine');
      }
      
      &::after {
        @include menuPsev ('bottomLine');
      }
      
      &-line {
        width: 100%;
        height: 2px;
        background-color: $mainTextColor;
        transition: 0.5s all;
      }
    }
  }
  
  .header__menu-lists {
    
    
    ul {
      @include baseRow(space-between);
      padding: 0;
    }

    li {
      list-style-type: none;
    }

    a {
      text-decoration: none;
      color: $mainTextColor;
    }
  }
  
}

@media (max-width: 576px) {
  .header__menu {
    
    .header__menu-button {
      display: flex;
     
    }
    
    .header__menu-lists {
      position: fixed;
      top: 0;
      bottom: 0;
      right: 0;
      left: 0;
      background-color: mainButtonColor();
      opacity: 0.9;
      padding-top: 90px;
      z-index: 1;
      display: none;

      ul {
        display: block;
        // flex-direction: column;
      }

      li {
        text-align: left;
        margin: 20px;
        padding-bottom: 20px;
        border-bottom: 1px solid $mainTextColor;
      }
    }

    .header__menu-button {
      top: 20px;
      right: 20px;
      width: 40px;
      height: 40px;

      .menu-button {
      } 
    }
  }
}

