<template lang="pug">
  section.integration#integration
    .integration__wrapper
      .integration__description.description
        .description__title-with-line.title-with-line
          .title-with-line__text integration
          .title-with-line__line
        .description__block.block
          .block__name games
          .block__text_normal Presented here you can find the games compatible with ZEUS 3000. The rifle is set as common controller and is simply integrated with minimal efforts to provide you the best experience of VR shooters. There are a lot of custom games developed for the ZEUS 3000 as well.
    .integration__slider
      hooper(:settings="hooperSettings")
        slide
          slide-item(
            :slideItemHeight="50"
            :slideItemImage="'bulletsorrow.png'"
            :slideItemContentName="'Bullet Sorrow VR'"
            :slideItemContentHref="'https://store.steampowered.com/app/521950/Bullet_Sorrow_VR/'"
          )
          slide-item(
            :slideItemHeight="50"
            :slideItemImage="'lasthope.png'"
            :slideItemContentName="'The Last Hope'"
            :slideItemContentHref="'https://store.steampowered.com/app/465240/Serious_Sam_VR_The_Last_Hope/'"
          )
        slide
          slide-item(
            :slideItemImage="'protonwar.png'"
            :slideItemContentName="'Protonwar'"
            :slideItemContentHref="'https://store.steampowered.com/app/461410/Protonwar/'"
            :slideItemContentShow="true"
          )
        slide
          slide-item(
            :slideItemImage="'spacepirate.png'"
            :slideItemContentName="'Space Pirate'"
            :slideItemContentHref="'https://store.steampowered.com/app/418650/Space_Pirate_Trainer/'"
            :slideItemContentShow="true"
          )
    .integration__slider__adaptive
      hooper
        slide
          slide-item(
            :slideItemImage="'lasthope.png'"
            :slideItemContentTitleBold="'serious sam '"
            :slideItemContentTitleNormal="'VR'"
            :slideItemContentShow="false"
            )
        slide
          slide-item(
            :slideItemImage="'bulletsorrow.png'"
            :slideItemContentTitleBold="'bullet sorrow '"
            :slideItemContentTitleNormal="'VR'"
            :slideItemContentShow="false"
            )
        slide
          slide-item(
            :slideItemImage="'spacepirate.png'"
            :slideItemContentTitleBold="'space pirate '"
            :slideItemContentTitleNormal="'trainer'"
            :slideItemContentShow="false"
            )
        slide
          slide-item(
            :slideItemImage="'protonwar.png'"
            :slideItemContentTitleBold="'protonwar'"
            :slideItemContentShow="false"
            )
    .swipe
      .swipe__text swipe
      .swipe__img
    .integration__wrapper  
      .description     
        .block
          .block__name tracking
          .block__text_normal ZEUS 3000 currently supports HTC Vive and Optitrack positional tracking technologies and can be easily deployed in your VR Arcade.
      .integration__icons.icons
        .icons__img
        .icons__img
        .icons__img
         
</template>

<script>
import SlideItem from '@/components/SlideItem';
import { Hooper, Slide } from 'hooper';
import 'hooper/dist/hooper.css';

export default {
  name: "integration-section",
  components: {
    Hooper,
    Slide,
    SlideItem
  },
  data: () => ({
    slideItemContentName: '',
    slideItemContentHref: '',
    slideItemContentShow: null,
    slideItemHeight: '',
    slideItemImage: '',
    disableButton: null,
    slideItemContentTitle: '',

    hooperSettings: {
      itemsToShow: 1,
      centerMode: true,
      infiniteScroll: true,
      autoPlay: true, 
      playSpeed: 2500,
      hoverPause: true,
      wheelControl: false,
      breakpoints: {
        425: {
          centerMode: false,
          itemsToShow: 2
        },
        768: {
          centerMode: false,
          itemsToShow: 2.5
        }
      }
    },
  }),
}

</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.integration {
  width: 100%;
  background-color: $mainBackgroundColor;
  padding-top: 96px;
  padding-bottom: 96px;
  overflow: hidden;

  .swipe{
    display: none;
    justify-content: flex-end;
    margin-bottom: 20px;
    margin-right: 20px;

    &__text{
      @include baseText(Regular, 18px, #464646);
      font-weight: 900;
      text-transform: uppercase;
    }

    &__img{
      @include headerTitleImage(15px, 15px, "~@/assets/images/integration/arrow_right.svg");
      margin: 3px;
    }
  }

  &__wrapper {
    @include wrapper();
  }
 
  .description {
    text-shadow: 0px 4px 10px rgba(0, 0, 0, 0.7);
    text-align: left;
 
    &__block {
      padding-top: 56px;
    }

    .block {
    
      &__name {
        font-size: 36px;
        text-transform: uppercase;
      }

      &__text {

        &_normal {
          @include baseText(Regular, 24px);
          line-height: 40px;
          padding-top: 42px;
        }
      }
    }
  }
  
  &__slider {
    height: 673px;
    padding-top: 46px;
    padding-bottom: 100px;
  }

  .icons {
    @include baseRow(space-around);
    padding-top: 64px;

    &__img {
      height: 67px;
      width: 261px;
      background-repeat: no-repeat;
      background-position: 50% 50%;
      
      &:nth-child(1) {
        background-image: url("~@/assets/images/integration/vive.png");
      }

      &:nth-child(2) {
        background-image: url("~@/assets/images/integration/optitrack.png");
      }

      &:nth-child(3) {
        background-image: url("~@/assets/images/integration/steam.png");
      }
    }
  }
  &__slider__adaptive{
    display: none;
  }
}
@media (max-width: 1200px) {
  .integration {
    
    &__wrapper {
      
    }
  
    .description {
      width: 98%;
      margin: auto;
  
      &__block {
        padding-top: 15px;
      }

      .block {

        &__name {
          font-size: 20px;
        }

        &__text {

          &_normal {
            line-height: 26px;
            font-size: 16px;
            padding-top: 15px;
          }
        }
      }
    }
    
    // &__slider {
    //   height: 340px;
    //   padding-bottom: 50px;
    // }

    .icons {
      padding-top: 40px;
      justify-content: space-around;
      margin: auto;

      &__img {
        height: 45px;
        width: 192px;
        background-size: contain;
       }
    }
  }
}

@media (max-width:768px) {
  .integration {
    
    .swipe{
      display: flex;
    }
    
    &__wrapper {
      padding: 0;
      margin: 0 16px;
    }
  
    .description {
      width: 90%;
      margin: auto;
  
      &__block {
        padding-top: 15px;
      }

      .block {
        padding: 0;

        &__name {
          font-size: 18px;
        }

        &__text {

          &_normal {
            line-height: 25px;
            font-size: 14px;
            padding-top: 15px;
          }
        }
      }
    }

    &__slider {
      display: none;
    }
  
    .icons {
      padding-top: 20px;
      justify-content: space-between;

      &__img {
        height: 31px;
        width: 182px;
        background-size: contain;
      }
    }
    .integration__slider__adaptive{
      display: block;
      padding-bottom: 50px;
    }
  }
}

@media (max-width:425px) {
  .integration {
     
    .description {
      width: 100%;
  
      &__block {
        padding-top: 15px;
      }

      .block {
  
        &__text {
          &_normal {
            padding-top: 10px;
          }
        }
      }
    }

    .icons {

      &__img {
        height: 21px;
        width: 82px;
      }
    }
  }
}

</style>