<template lang="pug">
  .base-input
    input.base-input__input-field(
      ref="input"
      :placeholder="computedPlaceholder"
      :name="name"
      :type="type"
      :autocomplete="autocomplete"
      :disabled="disabled"
      :class="{error: !!errorMessage}"
      v-model="inputValue"
      @blur="blurHandler"
      @keyup.enter.exact="blurHandler"
      )  
    .base-input__error-message(v-show="!!errorMessage") {{"! " + errorMessage}}
    

</template>

<script>


export default {
  name: "base_input",
  components: {
    
  },
  props: {
    name: {
      type: String,
      required: false,
      default: "",
    },
    type: {
      type: String,
      required: false,
      default: "text",
    },
    placeholder: {
      type: String,
      required: false,
      default: " ",
    },
    value: {
      type: String,
    },
    autocomplete: {
      type: String,
      required: false,
      default: "",
    },
    valid: {
      type: Boolean,
      required: false,
      default: false,
    },
    format: {
      type: Function,
      required: false,
      default: (val) => val,
    },
    disabled: {
      type: Boolean,
      required: false,
      default: false,
    },
    errorMessage: {
      type: String,
      required: false,
      default: null,
    },
  },
  mounted() {
    this.content = this.value
  },
  computed: {
    inputValue: {
      get() {
        return this.value
      },
      set($val) {
        this.$emit("input", $val, this.name)
      },
    },
    computedPlaceholder: function () {
      return this.label ? " " : this.placeholder
    },
  },
  watch: {
    value: {
      handler($val) {
        console.log($val)
        let $formatted = this.format($val)
        if ($val !== $formatted) {
          this.$emit("input", $formatted, this.name)
        }
      },
    },
  },
  methods: {
    blurHandler: function (e) {
      this.$emit("blur", e)
    },
  },
}
</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.base-input {
  position: relative;
 
  &__input-field {
    @include baseText(Regular, 24px, initial);
    width: 100%;
    min-height: 67px;
    padding: 0 18px;
    margin-top: 22px;
    background: $backgroundInput;
    outline: none;
    border-radius: 5px;
    border: 1px solid grayColor(100);
    box-sizing: border-box;
    
    &::placeholder {
      color: $placeholderInput;
    }

    &.error {
      border: 1px solid $errorColors;
      &:hover,
      &:focus {
         border: 1px solid $errorColors;
      }
    }

    &:hover {
      border-color: grayColor(300);
    }

    &:focus {
      border-color: grayColor(500);
    }

    &:disabled {
      background-color: grayColor(100);
      cursor: not-allowed;
    }
  }

  &__error-message {
    margin-top: 3px;
    color: $errorColors;
    text-align: left;
  }
}

@media (max-width: 992px){
  .base-input {
 
    &__input-field {
      @include baseText(Regular, 22px, initial);
    }
  }
}

@media (max-width: 768px){
  .base-input {
 
    &__input-field {
      @include baseText(Regular, 20px, initial);
    }
  }
}

@media (max-width: 425px){
  .base-input {
 
    &__input-field {
      @include baseText(Regular, 18px, initial);
    }
  }
}
</style>
