<template lang="pug">
  .info(
    :style="sliderBoxStyle()"
  )
    .info__dispersion-color
    .info__button.button(
      v-for="buttonInfo of buttonInfoLists"
      :key="buttonInfo.title"
    )
      .button__title {{buttonInfo.title}}
      .button__subtitle
        .button__text(
          v-for="subtitle of buttonInfo.subtitles"
          :key="subtitle"
        )
          p {{subtitle}}
   
</template>

<script>

export default {
  name: "info-button",
  components: {
  },
  data() {
    return {
     
    };
  },
  props: {
    top: {
      type: [String, Number],
      required: false,
      default: "",
    },
    bottom: {
      type: [String, Number],
      required: false,
      default: "",
    },
    left: {
      type: [String, Number],
      required: false,
      default: "",
    },
    right: {
      type: [String, Number],
      required: false,
      default: "",
    },
    animationDelay: {
      type: [String, Number],
      required: false,
      default: "",
    },
    buttonInfoLists: {
      type: Array,
      required: false,
    }
  },
  methods: {
    sliderBoxStyle: function () {
      return {
        top: this.top + 'px',
        bottom: this.bottom + 'px',
        left: this.left + 'px',
        right: this.right + 'px',
        animationDelay: this.animationDelay + 's'
      }
    },
  },
}
</script>

<style lang="scss" >
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.info {
  position: absolute;
  min-width: 25%;
  //opacity: 0;

  // &.animate {
  //   animation: opacityanimation 2s ease-in-out;
  //   animation-fill-mode: forwards;
  // }

  &__dispersion-color {
    position: absolute;
    left: -4%;
    top: -10px;
    width: 84%;
    height: 140%;
    background: rgba(24, 24, 24, 0.9);
    filter: blur(8px);
    z-index: 3;
  }
  
  .button {
    @include baseRow();
    position: relative;
    z-index: 4;
   
    &__title {
      position: relative;
      padding: 10px 25px;
      text-transform: uppercase;
      border: 1px solid $mainTextColor;
      border-radius: 40px;
      cursor: pointer;
      
      &::after {
        content: '';
        position: absolute;
        top: 50%;
        left: 100%;
        width: 315px;
        height: 1px;
        background-color: $mainTextColor;
      }
    }

    &__subtitle {
      text-align: left;
      line-height: 180%;
      font-size: 14px;
    }

    &__text {
      width: 65%;
      
      p {
        margin: 0;
        padding-left: 7px;
        
      }
    }
  }

   @keyframes opacityanimation {
    0% {
      opacity: 0;
      
    }
    50% {
      opacity: 0.5;
    }
    100% {
      opacity: 1;
      
    }
  }
}
@media (max-width: 1200px){
  // .info{

  //   .button {
     
  //     &__title{
  //       font-size: 10px;
  //     }

  //     &__text{
  //       display: none;
  //     }
  //   }
  // }
}
@media (max-width: 992px){
  .info{
    min-width: 50%;
    //display: block !important;

    .button {
      justify-content: space-between;
      margin: 0 5px;
     
      &__title{
        border: none;
        font-size: 12px;
        padding: 0;
      }

      &__title::after {
        content: none;
      }

      &__text{
        display: none;
      }
    }
  }
}

</style>
