<script>
import InfoButton from '@/components/InfoButton';

export default {
  name: "spicification-section",
  components: {
    InfoButton,
  
  },
  data: () => ({
    buttonInfoLists: {
      htc: [
        { 
          name: 'htc',
          title: 'HTC tracker', 
          subtitles: ['Connects rifle to VR system and tracks the movement of the rifle']
        },
      ],
      bracket: [
        { 
          name: 'bracket',
          title: 'Tracker mounting bracket',
          subtitles: ['Fixes the tracker on the rifle']
        }
      ],
      slot: [
        { 
          name: 'slot',
          title: 'tracker slot',
          subtitles: ['Provides the interconnection between tracker and riffle']
        }
      ],
      recoil: [
        { 
          name: 'recoil',
          title: 'Recoil mode indicator',
          subtitles: ['Reflects one of three available recoil modes']
        }
      ],
      teleport: [
        { 
          name: 'teleport',
          title: 'Teleport button',
          subtitles: ['Use the button to teleport to the another location within the scene']
        }
      ],
      recharge: [
        { 
          name: 'recharge',
          title: 'Recharge button',
          subtitles: ['Press and hold the button to eject magazine and reload the new one']
        }
      ],
      switching: [
        { 
          name: 'switching',
          title: 'Mode switching button',
          subtitles: ['Press the button to choose or change the recoil mode']
        }
      ],
      trigger: [
        { 
          name: 'trigger',
          title: 'Trigger',
          subtitles: ['Actuates the firing sequence of the rifle']
        }
      ],
    },
    nameButtonOnHover: '',
    stopAnimation: false
  }),
  methods: {
    checkButtonHover: function (buttonName) {
      if (this.nameButtonOnHover == buttonName) return true        
      return false
    },
    setNameButtonOnHover: function(buttonName) {
      this.stopAnimation = !this.stopAnimation
      
      if (buttonName) return this.nameButtonOnHover = buttonName
      return this.nameButtonOnHover = ''
    },
  },
  mounted(){
    this.$nextTick(() => {
      let elem = document.querySelector('.specification__gun');
      elem.scrollLeft = 610;
    });
  },
}

</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.specification {
  width: 100%;
  background-color: $mainBackgroundColor;
  padding-top: 96px;
  padding-bottom: 96px;
  overflow: hidden;
 
  &__wrapper {
    @include wrapper();
  }
 
  .description {
    text-shadow: 0px 4px 10px rgba(0, 0, 0, 0.7);
    text-align: left;

    &__text {

      &_normal {
        @include baseText(Regular, 24px);
        line-height: 40px;
        padding-top: 42px;
      }
    }
  }

  &__gun {
    position: relative;
  }

  &__svg {
    position: relative;
    padding-top: 70px;
    width: 1145px;
    
    .adaptivTable{
      display: none;
    }

    .overlay {
      position: absolute;
      top: 0;
      right: 0;

      &__htc {
        position: absolute;
        top: 60px;
        right: 237px;
        width: 170px;
        height: 80px;
        z-index: 5;
      }

      &__bracket {
        position: absolute;
        top: 140px;
        right: 237px;
        width: 170px;
        height: 45px;
        z-index: 5;
      }

      &__slot {
        position: absolute;
        top: 140px;
        right: 408px;
        width: 129px;
        height: 45px;
        z-index: 5;
      }

      &__recoil {
        position: absolute;
        top: 186px;
        right: 200px;
        width: 275px;
        height: 55px;
        z-index: 5;
      }

      &__teleport {
        position: absolute;
        top: 275px;
        right: 140px;
        width: 80px;
        height: 80px;
        border-radius: 50%;
        z-index: 5;
      }

      &__recharge {
        position: absolute;
        top: 330px;
        right: 238px;
        width: 82px;
        height: 45px;
        z-index: 5;
      }

      &__switching {
        position: absolute;
        top: 248px;
        right: 316px;
        width: 80px;
        height: 80px;
        border-radius: 50%;
        z-index: 5;
      }

      &__trigger {
        position: absolute;
        top: 295px;
        right: 430px;
        width: 82px;
        height: 86px;
        z-index: 5;
      }
    }
  }

  .swipe{
    display: none;
  }

  &__table {
    
    table {
      width: 100%;
      border-collapse: collapse;
      text-transform: uppercase;
      border-top: 8px solid $mainTextColor;
      margin-top: 128px;
      text-align: left;

      th {
        padding: 10px; 
        border: 1px solid $mainTextColor;
      }
      td {
        width: 281px;
        height: 64px;
        border: 1px solid $mainTextColor;
        padding-left: 14px;

        span {
          text-transform: lowercase;
        }
      }
    }
  }

  .specification__text__normal{
    display: none;
  }

  .boldText {
    @include baseText(Bold);
  }

  .svgFillWhite {
    fill: $mainTextColor;
  }

  .svgFillBlack {
    fill: $mainBackgroundColor;
    stroke: $mainBackgroundColor;
  }
}

.animateWhiteColor {
  animation: opacityanimation_white 2s ease-in-out;
  //animation-fill-mode: backwards;
  animation-iteration-count: infinite;
}

.animateBlackColor{
  animation: opacityanimation_black 2s ease-in-out;
  //animation-fill-mode: backwards;
  animation-iteration-count: infinite;
}

@keyframes opacityanimation_white {
  0% {
    fill: $mainBackgroundColor;
  }
  50% {
    fill: $mainTextColor;
  }
  100% {
    fill: $mainBackgroundColor;
  }
}

@keyframes opacityanimation_black {
  0% {
    fill: $mainTextColor;
    stroke:$mainTextColor;
  }
  50% {
    fill: $mainBackgroundColor;
    stroke:$mainBackgroundColor;
  }
  100% {
    fill: $mainTextColor;
    stroke:$mainTextColor;
  }
}

@media (max-width: 1200px){
  .specification {
    padding-top: 50px;
    padding-bottom: 0px;

    &__wrapper {
      margin: 0 16px;
    }
    .swipe{
      width: 1145px;
      display: flex;
      
      &__left{
        display: none;
      }

      &__right{
        display: none;
      }

      &__center{
        display: flex;
        justify-content: space-between;
        width: 100%;
        margin: 15px auto;
      }

      &__block{
        margin: auto;
        margin-top: 22px;
        display: flex;
        justify-content: center;
        width: 100px;
      }
      
      &__text{
        @include baseText(Bold);
        display: block;
        font-weight: bold;
      }

      &__arrow {
        margin: 3px;

        &.left{
          @include headerTitleImage(15px, 15px, "~@/assets/images/specification/arrow_left.svg");
        }

        &.right{
          @include headerTitleImage(15px, 15px, "~@/assets/images/specification/arrow_right.svg");
        }
      }
    }

    .description {
      
      &__text {

        &_normal {
          line-height: 25px;
          font-size: 14px;
          padding-top: 10px;
        }
      }
    }

    &__gun {
      overflow: auto;
      //margin: 0 16px;
    }
    
    &__table {
      width: 100%;
